import json
from hypothesis import strategies as st


@st.composite
def gen(draw):
    n = draw(st.integers(1, 6))
    alphabet = draw(st.sampled_from(["ab", "a", "abc"]))
    words = draw(st.lists(
        st.text(alphabet=alphabet, min_size=1, max_size=4),
        min_size=n, max_size=n,
    ))
    k = draw(st.integers(1, n))
    return json.dumps(words) + "\n" + json.dumps(k) + "\n"


def validate(inp):
    lines = [l for l in inp.split("\n") if l.strip() != ""]
    if len(lines) != 2:
        return False
    words = json.loads(lines[0])
    k = json.loads(lines[1])
    if not isinstance(words, list) or not isinstance(k, int) or isinstance(k, bool):
        return False
    n = len(words)
    if not (1 <= n <= 10**5):
        return False
    if not (1 <= k <= n):
        return False
    total = 0
    for w in words:
        if not isinstance(w, str):
            return False
        if not (1 <= len(w) <= 10**4):
            return False
        if not all('a' <= c <= 'z' for c in w):
            return False
        total += len(w)
    if total > 10**5:
        return False
    return True


def ref(inp):
    lines = [l for l in inp.split("\n") if l.strip() != ""]
    words = json.loads(lines[0])
    k = json.loads(lines[1])
    n = len(words)
    answer = []
    for i in range(n):
        rem = words[:i] + words[i + 1:]
        if len(rem) < k:
            answer.append(0)
            continue
        best = 0
        maxlen = max(len(w) for w in rem)
        for L in range(1, maxlen + 1):
            counts = {}
            for w in rem:
                if len(w) >= L:
                    p = w[:L]
                    counts[p] = counts.get(p, 0) + 1
            if any(c >= k for c in counts.values()):
                best = max(best, L)
        answer.append(best)
    return json.dumps(answer)
